// PostHog Helper - Ensures consistent tracking across the site
(function() {
    'use strict';
    
    // Ensure window.posthog is always available
    if (!window.posthog) {
        window.posthog = {
            capture: function() {},
            identify: function() {},
            setPersonProperties: function() {},
            alias: function() {},
            get_distinct_id: function() { return 'anonymous'; },
            __stub: true
        };
    }
    
    // Safe tracking function that always works
    window.trackEvent = function(eventName, properties) {
        console.log('[PostHog] Event:', eventName, 'Type: capture', 'Properties:', properties || {});
        if (window.posthog && typeof window.posthog.capture === 'function') {
            try {
                // Add common properties to all events
                const enrichedProperties = Object.assign({
                    page_url: window.location.href,
                    page_path: window.location.pathname,
                    page_title: document.title,
                    timestamp: new Date().toISOString(),
                    user_agent: navigator.userAgent,
                    screen_width: window.screen.width,
                    screen_height: window.screen.height,
                    viewport_width: window.innerWidth,
                    viewport_height: window.innerHeight
                }, properties || {});
                
                console.log('[PostHog] Enriched properties:', enrichedProperties);
                window.posthog.capture(eventName, enrichedProperties);
                console.log('[PostHog] ✓ Event captured successfully:', eventName);
            } catch (e) {
                console.warn('[PostHog] ✗ Tracking error:', e);
            }
        } else {
            console.warn('[PostHog] ✗ PostHog not available, event not tracked:', eventName);
        }
    };
    
    // Safe identify function
    window.trackIdentify = function(userId, properties) {
        console.log('[PostHog] Event: identify', 'Type: identify', 'User ID:', userId, 'Properties:', properties || {});
        if (window.posthog && typeof window.posthog.identify === 'function') {
            try {
                window.posthog.identify(userId, properties || {});
                console.log('[PostHog] ✓ User identified successfully:', userId);
            } catch (e) {
                console.warn('[PostHog] ✗ Identify error:', e);
            }
        } else {
            console.warn('[PostHog] ✗ PostHog not available, identify not tracked:', userId);
        }
    };
    
    // Safe setPersonProperties function
    window.trackPersonProperties = function(properties) {
        console.log('[PostHog] Event: setPersonProperties', 'Type: setPersonProperties', 'Properties:', properties || {});
        if (window.posthog && typeof window.posthog.setPersonProperties === 'function') {
            try {
                window.posthog.setPersonProperties(properties || {});
                console.log('[PostHog] ✓ Person properties set successfully');
            } catch (e) {
                console.warn('[PostHog] ✗ setPersonProperties error:', e);
            }
        } else {
            console.warn('[PostHog] ✗ PostHog not available, person properties not set');
        }
    };
    
    // Safe alias function
    window.trackAlias = function(anonymousId, identifiedId) {
        console.log('[PostHog] Event: alias', 'Type: alias', 'Anonymous ID:', anonymousId, 'Identified ID:', identifiedId);
        if (window.posthog && typeof window.posthog.alias === 'function') {
            try {
                window.posthog.alias(anonymousId, identifiedId);
                console.log('[PostHog] ✓ Alias created successfully:', anonymousId, '->', identifiedId);
            } catch (e) {
                console.warn('[PostHog] ✗ Alias error:', e);
            }
        } else {
            console.warn('[PostHog] ✗ PostHog not available, alias not created');
        }
    };
    
    // Wait for PostHog to be fully loaded
    if (window.posthog && !window.posthog.__loaded) {
        window.posthog.onFeatureFlags(function() {
            // PostHog is ready
            window.posthog.__ready = true;
        });
    } else if (window.posthog) {
        window.posthog.__ready = true;
    }
})();

